mapper.select:
SELECT COUNT(DISTINCT CONCAT(a.id, '_', asub.session_id, '_', asub.subject_type, '_', asub.subject_id)) FROM assignment a JOIN assessment_submission asub ON a.id = asub.assignment_id LEFT JOIN slot_sessions ss ON asub.session_id = ss.session_id LEFT JOIN venue v ON ss.venue_id = v.id LEFT JOIN sys_user su ON asub.subject_type = 'INDIVIDUAL' AND asub.subject_id = su.user_id LEFT JOIN sys_group sg ON asub.subject_type = 'GROUP' AND asub.subject_id = sg.group_id
WHERE a.id = #{assignmentId}
AND asub.session_id = #{sessionId}
AND ( (asub.subject_type = 'INDIVIDUAL' AND ( su.user_name LIKE CONCAT('%', #{searchQuery}, '%') OR asub.subject_id LIKE CONCAT('%', #{searchQuery}, '%') )) OR (asub.subject_type = 'GROUP' AND ( sg.group_name LIKE CONCAT('%', #{searchQuery}, '%') OR asub.subject_id LIKE CONCAT('%', #{searchQuery}, '%') )) )

SELECT * FROM assessment_submission
WHERE assignment_id = #{assignmentId}
AND session_id = #{sessionId}
AND subject_type = #{subjectType}
AND subject_id = #{subjectId}
AND examiner_id = #{examinerId}
LIMIT 1

